import icontract
from typing import List


@icontract.ensure(lambda result: all(result[i] <= result[i + 1] for i in range(len(result) - 1)))
@icontract.ensure(lambda a, result: sorted(result) == sorted(a))
def SelectionSort(a: List[int]) -> List[int]:
    res = list(a)
    n = len(res)
    for i in range(n):
        m = i
        for j in range(i + 1, n):
            if res[j] < res[m]:
                m = j
        res[i], res[m] = res[m], res[i]
    return res
